void main() {
  // Simulating the sort
  List<String> enumValues = ['השלמת מסמכים', 'דחייה לגופה', 'זימון ועדה', 'נגמר השעון'];

  // Simulate some data
  List<String> data = ['נגמר השעון', 'השלמת מסמכים', 'דחייה לגופה', 'זימון ועדה', 'השלמת מסמכים'];

  // Sort using the same logic
  data.sort((a, b) {
    if (a.isEmpty != b.isEmpty) return a.isEmpty ? 1 : -1;
    final c = enumValues.indexOf(a).compareTo(enumValues.indexOf(b));
    if (c != 0) return c;
    return 0;
  });

  print('Sorted: $data');
  print('Expected: [השלמת מסמכים, השלמת מסמכים, דחייה לגופה, זימון ועדה, נגמר השעון]');
}
